/*
 * @interlace/ui — animations and motion tokens used by primitives + decorative components.
 * Import once in the consuming app's global stylesheet:
 *   @import "@interlace/ui/styles/tokens.css";
 *
 * Design-system colors are intentionally not defined here — fumadocs sites
 * inherit them from `fumadocs-ui/css/<theme>.css` and overlay brand overrides
 * in their own global.css.
 */

@theme inline {
  /* MagicUI: shimmer-button */
  --animate-shimmer-slide: shimmer-slide var(--speed) ease-in-out infinite
    alternate;
  --animate-spin-around: spin-around calc(var(--speed) * 2) infinite linear;

  /* MagicUI: animated-gradient-text */
  --animate-gradient: gradient 8s linear infinite;

  /* MagicUI: marquee */
  --animate-marquee: marquee var(--duration) infinite linear;
  --animate-marquee-vertical: marquee-vertical var(--duration) linear infinite;

  /* Aceternity: background-gradient-animation */
  --animate-first: moveVertical 30s ease infinite;
  --animate-second: moveInCircle 20s reverse infinite;
  --animate-third: moveInCircle 40s linear infinite;
  --animate-fourth: moveHorizontal 40s ease infinite;
  --animate-fifth: moveInCircle 20s ease infinite;

  /* Primitives: accordion */
  --animate-accordion-down: accordion-down 0.2s ease-out;
  --animate-accordion-up: accordion-up 0.2s ease-out;

  @keyframes shimmer-slide {
    to {
      transform: translate(calc(100cqw - 100%), 0);
    }
  }
  @keyframes spin-around {
    0% {
      transform: translateZ(0) rotate(0);
    }
    15%,
    35% {
      transform: translateZ(0) rotate(90deg);
    }
    65%,
    85% {
      transform: translateZ(0) rotate(270deg);
    }
    100% {
      transform: translateZ(0) rotate(360deg);
    }
  }
  @keyframes gradient {
    to {
      background-position: var(--bg-size, 300%) 0;
    }
  }
  @keyframes marquee {
    from {
      transform: translateX(0);
    }
    to {
      transform: translateX(calc(-100% - var(--gap)));
    }
  }
  @keyframes marquee-vertical {
    from {
      transform: translateY(0);
    }
    to {
      transform: translateY(calc(-100% - var(--gap)));
    }
  }
  @keyframes moveHorizontal {
    0% {
      transform: translateX(-50%) translateY(-10%);
    }
    50% {
      transform: translateX(50%) translateY(10%);
    }
    100% {
      transform: translateX(-50%) translateY(-10%);
    }
  }
  @keyframes moveInCircle {
    0% {
      transform: rotate(0deg);
    }
    50% {
      transform: rotate(180deg);
    }
    100% {
      transform: rotate(360deg);
    }
  }
  @keyframes moveVertical {
    0% {
      transform: translateY(-50%);
    }
    50% {
      transform: translateY(50%);
    }
    100% {
      transform: translateY(-50%);
    }
  }
  @keyframes accordion-down {
    from {
      height: 0;
    }
    to {
      height: var(--radix-accordion-content-height);
    }
  }
  @keyframes accordion-up {
    from {
      height: var(--radix-accordion-content-height);
    }
    to {
      height: 0;
    }
  }
}

/* Border Beam — pure CSS animation, used by @interlace/ui/magicui/border-beam.
 * Wrapped in `@layer interlace.primitives` so the cascade is deterministic.
 * `@keyframes` declarations can live outside a layer (they have a global
 * scope per spec), but the consuming utility class .animate-border-beam goes
 * in the layer for override-friendliness. */
@keyframes border-beam {
  0% {
    offset-distance: var(--border-beam-initial, 0%);
  }
  100% {
    offset-distance: calc(100% + var(--border-beam-initial, 0%));
  }
}

@layer interlace.primitives {
.animate-border-beam {
  animation: border-beam var(--border-beam-duration, 6s) linear infinite;
  animation-direction: var(--border-beam-direction, normal);
}

/*
 * Accessibility — respect prefers-reduced-motion.
 * Industry-canon practice (MUI, Vercel, Linear, Stripe, GitHub all do this).
 * Disables every CSS-driven animation registered above when the user has
 * motion-sensitivity preferences. JS-driven motion (motion/react, canvas)
 * is gated per-component via the useReducedMotion hook.
 *
 * ⚠️ THIS LIST IS THE SECOND LAYER, NOT THE FIRST.
 *
 * The primary reduced-motion guarantee is the wildcard in `preflight.css`
 * (`*, *::before, *::after { animation-duration: 0.01ms !important; … }`),
 * and it is the only thing that reaches the animations no selector here can
 * name: Tailwind's own `animate-pulse` / `animate-bounce`, and the
 * `data-[open]:animate-in` / `data-[closed]:animate-out` variants that every
 * Dialog, Sheet, Popover, Tooltip, DropdownMenu and ContextMenu emits (those
 * compile to `.data-\[open\]\:animate-in`, which `.animate-in` does not
 * match). Delete the preflight wildcard and most of the DS starts animating
 * under `reduce` with nothing here to catch it — `motion-contract-lock`
 * fails if anyone tries.
 *
 * What this list buys on top of the wildcard is worth having, which is why
 * both exist:
 *   1. `animation: none` instead of a 0.01ms clamp — the animation never
 *      runs at all, rather than running one imperceptible cycle.
 *   2. cover for the à-la-carte import path. Every stylesheet here is a
 *      separate `exports` entry, so a consumer can import tokens.css +
 *      theme.css and skip preflight.css; then this list is the ONLY defence.
 *
 * Rule for adding to it: every bare `animate-*` utility that `packages/ui/src`
 * puts on an element belongs here. `.animate-pulse` did not, for the whole of
 * Skeleton's life, and the à-la-carte path pulsed for reduce users.
 */
@media (prefers-reduced-motion: reduce) {
  .animate-shimmer-slide,
  .animate-spin-around,
  .animate-gradient,
  .animate-marquee,
  .animate-marquee-vertical,
  .animate-first,
  .animate-second,
  .animate-third,
  .animate-fourth,
  .animate-fifth,
  .animate-border-beam,
  .animate-accordion-down,
  .animate-accordion-up,
  .animate-fade-in-up,
  .animate-slide-in-left,
  .animate-scale-in,
  .animate-pulse,
  .animate-meteor,
  .animate-meteor-effect {
    animation: none !important;
    transition: none !important;
  }
}
} /* end @layer interlace.primitives */

/*
 * @interlace/ui — foundation tokens: type scale, spacing scale, radius,
 * container widths, font families. The brand-INVARIANT structural layer.
 *
 * Import in the consuming app AFTER tokens.css, BEFORE/independent of the
 * brand layer (interlace-theme.css):
 *
 *   @import "@interlace/ui/styles/tokens.css";       motion
 *   @import "@interlace/ui/styles/foundation.css";   type + spacing + radius   ← THIS FILE
 *   @import "@interlace/ui/styles/theme.css";         fumadocs color bridge
 *   @import "@interlace/ui/styles/interlace-theme.css"; brand color values
 *
 * Why a separate file (not theme.css / interlace-theme.css):
 *   - theme.css is the fumadocs COLOR bridge; interlace-theme.css is the brand
 *     COLOR layer (and is not imported by every consumer — docs omits it).
 *   - Type/spacing/radius/container are brand-invariant STRUCTURE that EVERY
 *     consumer needs so primitives (Typography/Stack/Grid/Box/Container) map to
 *     real tokens (R19) instead of Tailwind defaults. Keeping them here, in a
 *     universally-imported file, fixes the prior gap where the radius bridge +
 *     font tokens lived only in the registry app (apps/registry/globals.css) and
 *     non-registry consumers silently fell back to Tailwind defaults.
 *
 * Sources: TYPOGRAPHY_PHILOSOPHY.md (type scale, body/code contracts, fluid
 * type, reading-vs-UI modes) + LAYOUT_PHILOSOPHY.md (#2 container widths, #3
 * spacing token table). Values are ours; the 3-layer SYSTEM mirrors the concept,
 * not any one project's numbers.
 *
 * Self-contained: every value is a literal here, so the file works even when a
 * consumer omits the brand layer. Brand-coupled tokens (e.g. --subtle, derived
 * from the brand primary) stay in interlace-theme.css.
 *
 * Fonts: families only. Inter / JetBrains Mono are loaded by the app (next/font
 * or @font-face with font-display: swap, per TYPOGRAPHY_PHILOSOPHY "no FOIT").
 * This file names the family stack; it does not ship font binaries.
 */

@theme {
  /* ── Font families ─────────────────────────────────────────────── */
  /* font-body / font-mono utilities. --font-sans aliases body so stock
     shadcn `font-sans` usages pick up Inter without a rename. */
  --font-body:
    'Inter', 'Inter Variable', system-ui, -apple-system, BlinkMacSystemFont,
    'Segoe UI', sans-serif;
  --font-sans: var(--font-body);
  --font-mono:
    'JetBrains Mono', 'JetBrains Mono Variable', 'SF Mono', Menlo, Consolas,
    'Liberation Mono', monospace;

  /* ── Type scale (font-size + paired line-height) ───────────────────
     SIX heading levels max (TYPOGRAPHY "heading scale"). Display end fluids
     on a single curve; body stays FIXED (no clamp on body — confuses readers).
     Generates text-h1…text-h6, text-body, text-long, text-ui, text-code, etc. */
  --text-h1: clamp(2.5rem, 4vw + 1rem, 3.5rem); /* 40 → 56px */
  --text-h1--line-height: 1.1;
  --text-h2: 1.875rem; /* 30px */
  --text-h2--line-height: 1.2;
  --text-h3: 1.5rem; /* 24px */
  --text-h3--line-height: 1.25;
  --text-h4: 1.25rem; /* 20px */
  --text-h4--line-height: 1.3;
  --text-h5: 1.0625rem; /* 17px */
  --text-h5--line-height: 1.4;
  --text-h6: 1rem; /* 16px */
  --text-h6--line-height: 1.4;
  --text-body: 1rem; /* 16px base body */
  --text-body--line-height: 1.6;
  --text-long: 1.0625rem; /* 17px long-form reading */
  --text-long--line-height: 1.7;
  --text-ui: 0.875rem; /* 14px UI text */
  --text-ui--line-height: 1.5;
  --text-ui-sm: 0.8125rem; /* 13px dense UI */
  --text-ui-sm--line-height: 1.5;
  --text-code: 0.875rem; /* 14px code blocks */
  --text-code--line-height: 1.6;
  --text-caption: 0.8125rem; /* 13px captions / eyebrows */
  --text-caption--line-height: 1.5;

  /* ── Line-height scale (standalone leading-* utilities) ─────────── */
  --leading-body: 1.6;
  --leading-long: 1.7;
  --leading-ui: 1.5;
  --leading-heading: 1.2;

  /* ── Letter-spacing (tracking-* utilities) ─────────────────────────
     0 body; tighten only headings ≥32px. */
  --tracking-display: -0.02em;
  --tracking-heading: -0.01em;

  /* Weight ladder (TYPOGRAPHY "weight ladder"): 400 body / 500 UI emphasis /
     600 strong + headings / 700 page headings — NO 900 ever. Uses Tailwind's
     built-in font-normal/font-medium/font-semibold/font-bold; NOT redefined as
     --font-weight-* tokens (those would collide with the --font-* family keys
     on the shared `font-<name>` utility namespace). */

  /* ── Spacing scale (LAYOUT #3 — the six-step token table) ──────────
     Named keys → p-xs / gap-md / m-lg / py-xl utilities, DS-owned (R19).
     Additive: the numeric Tailwind scale (p-4, gap-6) is untouched. */
  --spacing-xs: 0.5rem; /*  8px — inline chip / badge padding */
  --spacing-sm: 1rem; /* 16px — card padding, mobile page padding */
  --spacing-md: 1.5rem; /* 24px — card-grid gaps */
  --spacing-lg: 2.5rem; /* 40px — mobile section vertical padding */
  --spacing-xl: 4rem; /* 64px — desktop section vertical padding */
  --spacing-2xl: 6rem; /* 96px — hero / final-CTA breathing room */

  /* ── Radius (8/12/16 three-step scale) ─────────────────────────────
     PROMOTED from apps/registry/globals.css to the shared package so
     rounded-sm/md/lg are DS-owned in every consumer (docs/storybook too),
     not the Tailwind defaults (2/6/8px). */
  --radius-sm: 0.5rem; /*  8px */
  --radius-md: 0.75rem; /* 12px */
  --radius-lg: 1rem; /* 16px */

  /* ── Container widths (LAYOUT #2 — four sizes only) ─────────────────
     Generates max-w-prose / max-w-content / max-w-wide. `full` = no max-width
     (omit the utility). ad-hoc max-w-3xl/4xl/5xl/6xl are forbidden by R21. */
  --container-prose: 65ch; /* long-form text */
  --container-content: 64rem; /* 1024px — default landing section */
  --container-wide: 80rem; /* 1280px — card-grid-heavy section */

  /* Floating-surface width. NOT a `Container size` — these three above are
     the page-layout ladder. This one sizes detached chrome (toast stack,
     side-anchored panels) that must stay narrower than any section. Lives
     here rather than as `max-w-[420px]` at the call site so the toast
     stack and anything else that docks to a viewport edge agree on one
     number (R19/R21). */
  --container-float: 26.25rem; /* 420px — edge-docked toast / panel stack */

  /* ── Breakpoints (BREAKPOINT_PHILOSOPHY — 4-tier system) ─────────────
     Codified to override Tailwind v4's defaults (640/768/1024/1280/1536)
     with a tighter 4-tier ladder aligned to our MIN_VIEWPORT floor.
     `rem`-based so user-zoom + browser font-size scaling respect the
     breakpoints (accessibility win — px-only breakpoints ignore zoom).

       sm = 30rem  = 480 CSS px @ 16px root font → handheld floor
       md = 48rem  = 768 CSS px @ 16px root font → tablet / large phone
       lg = 64rem  = 1024 CSS px → laptop
       xl = 80rem  = 1280 CSS px → desktop

     Generates `sm:` / `md:` / `lg:` / `xl:` Tailwind variants. The
     `2xl` tier is INTENTIONALLY omitted — `Container size="wide"`
     (1280px) is the largest section width the DS supports, so a
     `2xl:` variant has no DS-side meaning.

     Aligned with the MIN_VIEWPORT contract: a primitive declaring
     `MIN_VIEWPORT=480` is exactly the `sm:` floor; `768` is `md:`. */
  --breakpoint-sm: 30rem;   /* 480px — handheld */
  --breakpoint-md: 48rem;   /* 768px — tablet */
  --breakpoint-lg: 64rem;   /* 1024px — laptop */
  --breakpoint-xl: 80rem;   /* 1280px — desktop */
}

/* ── Reading-mode vs UI-mode component classes ──────────────────────
   TYPOGRAPHY "Reading mode vs UI mode": the call site declares intent.
   The Typography primitive applies the right class by default; consumers
   reach for these directly on prose containers. Body is FIXED size (never
   fluid); measure is bounded ≤75ch (non-negotiable). */
@layer components {
  .prose-body {
    font-family: var(--font-body);
    font-size: var(--text-body);
    line-height: var(--leading-body);
    max-width: 65ch;
  }
  .prose-long {
    font-family: var(--font-body);
    font-size: var(--text-long);
    line-height: var(--leading-long);
    max-width: 75ch;
    text-rendering: optimizeLegibility;
  }
  .ui-text {
    font-family: var(--font-body);
    font-size: var(--text-ui);
    line-height: var(--leading-ui);
  }
  .ui-text-sm {
    font-family: var(--font-body);
    font-size: var(--text-ui-sm);
    line-height: var(--leading-ui);
  }
}

/*
 * @interlace/ui — preflight: the token-aware baseline that goes beyond
 * Tailwind's own preflight. Imported by `index.css` as part of the
 * canonical CSS contract; all rules live inside `@layer interlace.preflight`
 * so brand / consumer overrides land cleanly in higher-priority layers
 * without specificity wars.
 *
 *   @import "tailwindcss";                              Tailwind's own preflight
 *   @import "@interlace/ui/styles/index.css";           ← preferred (single import)
 *
 * Or, if a consumer must compose the layers manually:
 *   @import "@interlace/ui/styles/tokens.css";          motion
 *   @import "@interlace/ui/styles/foundation.css";      type + spacing + radius
 *   @import "@interlace/ui/styles/preflight.css";       ← THIS FILE (token-aware baseline)
 *   @import "@interlace/ui/styles/theme.css";            fumadocs color bridge
 *   @import "@interlace/ui/styles/interlace-theme.css";  brand color values
 *
 * Why this file exists (the "more advanced than Tailwind preflight" the
 * Interlace DS owes its consumers):
 *   1. Tailwind's preflight resets margins / borders / box-sizing — necessary
 *      but VALUELESS without tokens. We layer on the token-aware defaults the
 *      brand depends on (selection color, focus ring, scrollbar tint,
 *      ::placeholder, Inter font-features, text-wrap balance on headings).
 *   2. It enforces DESIGN_PRINCIPLES at the document baseline — every page
 *      that imports the DS inherits the right type rendering, the right focus
 *      visibility (WCAG 2.2 SC 2.4.13), the right reduced-motion contract.
 *   3. It owns the per-component min-viewport contract: `data-min-viewport`
 *      sets a container so a primitive can warn (dev) when rendered below
 *      its declared minimum — see DESIGN_PRINCIPLES.md #14.
 *
 * Forbidden in this file: brand color values (those live in interlace-theme.css);
 * component-specific styles (those live in the primitive's cva); JS coupling.
 * Allowed: token-referencing `var(--*)`, prefers-reduced-motion + prefers-color-scheme
 * queries, container-type declarations.
 */

/* ─────────────────────────────────────────────────────────────────
 * 1. Body + heading baseline
 *    Inter for prose/UI; JetBrains Mono inherited where set. font-feature-settings
 *    activates cv11 (single-storey a → matches our written language) + ss01
 *    (alternate g). text-rendering: optimizeLegibility on body only (not
 *    monospace — that's mechanical, not prose).
 * ──────────────────────────────────────────────────────────────── */
@layer interlace.preflight {
body {
  font-family: var(--font-body);
  font-feature-settings:
    'cv11',
    'ss01',
    'calt',
    'liga';
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  background-color: var(--background);
  color: var(--foreground);
}

/* Headings get text-wrap: balance for two-line + better visual rhythm.
 * Browsers without support (older Safari/Firefox) gracefully fall back to
 * normal wrapping. */
h1,
h2,
h3,
h4,
h5,
h6 {
  text-wrap: balance;
}

/* Prose paragraphs get text-wrap: pretty (avoids orphan-word last lines).
 * Same graceful fallback contract. */
p {
  text-wrap: pretty;
}

/* Monospace inheritance — code/kbd/samp/pre use the DS mono token,
 * not the browser default (Courier). */
code,
kbd,
samp,
pre {
  font-family: var(--font-mono);
  font-feature-settings: 'calt';
}

/* ─────────────────────────────────────────────────────────────────
 * 2. Selection + focus contract
 *    Selection: brand accent at low alpha (legible on both light + dark
 *    surfaces). Focus-visible: 2px solid --ring, 2px offset (WCAG 2.2
 *    SC 2.4.13 — ≥3:1 contrast, ≥2px thick). NEVER outline: none without a
 *    replacement.
 * ──────────────────────────────────────────────────────────────── */
::selection {
  background-color: color-mix(in oklch, var(--ring) 24%, transparent);
  color: var(--foreground);
}

/* The DS focus ring contract — every interactive primitive inherits this
 * unless it explicitly opts out for a designed alternative. */
:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
  border-radius: 2px;
}

/* No outline on click-only focus (mouse / touch users don't need it; SC 2.4.7
 * is satisfied by :focus-visible). */
:focus:not(:focus-visible) {
  outline: none;
}

/* ─────────────────────────────────────────────────────────────────
 * 3. Form-element inheritance
 *    Tailwind preflight already resets borders + appearance, but input/textarea/
 *    button still inherit Times/Helvetica on some browsers. Force the DS font.
 *    ::placeholder uses --muted-foreground for AA contrast on every surface.
 * ──────────────────────────────────────────────────────────────── */
input,
textarea,
select,
button {
  font-family: inherit;
  font-feature-settings: inherit;
}

::placeholder {
  color: var(--muted-foreground);
  opacity: 1; /* Firefox defaults to 0.54 — restore full opacity for AA. */
}

/* ─────────────────────────────────────────────────────────────────
 * 4. Image + media defaults
 *    Responsive by default (max-width: 100%). aspect-ratio preserved via
 *    height: auto. vertical-align: middle prevents the descender gap
 *    under inline images.
 * ──────────────────────────────────────────────────────────────── */
img,
picture,
video,
canvas,
svg {
  display: block;
  max-width: 100%;
  height: auto;
  vertical-align: middle;
}

/* ─────────────────────────────────────────────────────────────────
 * 5. Scrollbar tint
 *    A subtle DS-tinted scrollbar on long surfaces (modern browsers). Avoids
 *    the heavy OS-default look without going invisible. Webkit + standards
 *    syntax both included for coverage.
 * ──────────────────────────────────────────────────────────────── */
* {
  scrollbar-width: thin;
  scrollbar-color: var(--border) transparent;
}

*::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}
*::-webkit-scrollbar-track {
  background: transparent;
}
*::-webkit-scrollbar-thumb {
  background-color: var(--border);
  border-radius: 9999px;
  border: 2px solid transparent;
  background-clip: padding-box;
}
*::-webkit-scrollbar-thumb:hover {
  background-color: var(--muted-foreground);
}

/* ─────────────────────────────────────────────────────────────────
 * 6. Motion contract
 *    Smooth-scroll on document navigation (anchor links, history nav).
 *    prefers-reduced-motion overrides EVERYTHING — including any animation
 *    a component sets — by clamping durations to 0.01ms (per WCAG SC 2.3.3
 *    + the Tailwind motion-safe philosophy). DESIGN_PRINCIPLES #7.
 * ──────────────────────────────────────────────────────────────── */
html {
  scroll-behavior: smooth;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* ─────────────────────────────────────────────────────────────────
 * 7. Tabular numerals for data
 *    Vertically-scanned number lists / tables / live-changing counters get
 *    tabular-nums + lining figures, so digits don't jump as the value
 *    updates. TYPOGRAPHY_PHILOSOPHY "Numerals".
 * ──────────────────────────────────────────────────────────────── */
table,
[role='grid'],
[data-tabular-nums] {
  font-variant-numeric: tabular-nums lining-nums;
}

/* ─────────────────────────────────────────────────────────────────
 * 8. Min-viewport contract — DESIGN_PRINCIPLES #14
 *    Each primitive declares the smallest viable viewport via the
 *    `data-min-viewport="<px>"` attribute on its root. preflight establishes
 *    the container so consumers (or a future preflight v2 with a
 *    `body[data-interlace-dev]` gate) can render a warning when a primitive
 *    is mounted in a container narrower than its declared minimum.
 *
 *    Today the attribute is documented machine-readable metadata (visible in
 *    devtools, queryable in E2E tests). The visual dev-mode warning is wired
 *    in apps that opt-in via `<body data-interlace-dev>`.
 * ──────────────────────────────────────────────────────────────── */
/*
 * ⚠️ The containment is GATED on the dev opt-in, and that gate is load-bearing.
 *
 * `container-type: inline-size` applies inline-axis SIZE CONTAINMENT, which
 * makes an element's intrinsic inline size exactly ZERO. Applied unconditionally
 * — as it was until 2026-08-10 — every primitive that declares
 * `data-min-viewport` AND is shrink-to-fit (`inline-block`, `inline-flex`, or a
 * content-sized flex item) computed `width: 0px`, its children overflowed the
 * box, and the component rendered as a sliver or as one word per line.
 *
 * Measured on `ReadingTime`: 0px with the rule, 28.84px without it. It also
 * zeroed NumberField (154px), ToggleGroup (120px), PublishedDate (88px), the
 * Delta cell in MetricTable, and FocusRing — and it was live on
 * ds.interlace.tools, where these render as the public previews.
 *
 * The containment exists only so the `@container` queries below can fire. Those
 * queries are themselves gated on `body[data-interlace-dev]`, so outside dev
 * mode the containment bought nothing and cost this. Gating it matches the
 * queries it serves.
 *
 * Known limitation, accepted deliberately: inside the dev gate a shrink-to-fit
 * primitive still collapses, because there is no CSS selector for "block-level"
 * and containment is meaningless on an inline box. A dev-only visual artefact in
 * an opt-in debugging mode is a far better trade than a zero-width component in
 * production, which is what we had.
 */
body[data-interlace-dev] [data-min-viewport] {
  container-type: inline-size;
}

body[data-interlace-dev] [data-min-viewport='320'] {
  @container (max-width: 319px) {
